class.description:
Redéfinir [method BTNode._tick] (et si besoin [method BTNode._on_enter] / [method BTNode._on_exit]). Sans script, l'action réussit immédiatement et l'éditeur affiche un avertissement de configuration.
[codeblock]
extends BTAction

@export var duree_repos := 2.0

func _on_enter() -> void:
	get_agent().velocity = Vector2.ZERO

func _tick(_delta: float) -> int:
	return SUCCESS if get_running_time() >= duree_repos else RUNNING
[/codeblock]
